import test from 'node:test';import assert from 'node:assert/strict';import crypto from 'node:crypto';import {A,assets,c,createCanvas} from './load-assets.mjs';import {createJangmokEnvironment} from '../environment.mjs';import {renderNativeHome} from '../render.mjs';
test('all12 pinned poses render with unchanged ground pivot indoors and outdoors',()=>{const env=createJangmokEnvironment(A),a=createCanvas(696,464),b=createCanvas(696,464);for(const scene of ['family_1F','coastal_1F'])for(let pose=0;pose<12;pose++){assert.equal(A.actors[pose].width,107);assert.equal(A.actors[pose].height,107);renderNativeHome(a.getContext('2d'),{contract:c,assets,environment:env,status:{scene,foot:scene==='coastal_1F'?[450,315]:[348,278],facing:'down',pose}});b.width=696;b.height=464;b.getContext('2d').drawImage(assets[scene],0,0);b.getContext('2d').drawImage(A.actors[pose],(scene==='coastal_1F'?450:348)-53,(scene==='coastal_1F'?315:278)-90);assert.deepEqual(a.getContext('2d').getImageData(0,0,696,464).data,b.getContext('2d').getImageData(0,0,696,464).data);const r=renderNativeHome(a.getContext('2d'),{contract:c,assets,environment:env,status:{scene:'exterior',foot:[3280,600],facing:'down',pose}});assert.equal(r.pose,pose);assert.deepEqual(r.actorPivot,[53,90]);assert.equal(r.actualBrowserGaitVerified,false);globalThis.gc?.()}});
